"""Wave 29A: priority hints are fast, and exactly what they were.

``view.hints`` / ``view.rules_view`` open a read-only pass (app/rules/read_pass.py): the statics table, what each permanent is after the
layers, each card's printed values and the scans of the table that every card in the viewer's hand asks for are worked out once per view
instead of once per card and static ability (80 permanents, 3 spells on the stack, 7 cards in hand: ~2.5 s per call before).

The proof that nothing else changed:

* ``tests/fixtures/wave29a_hints_golden.json`` was generated by the code *before* the pass existed (the wave 28 head, fef8b49) from the boards
  in tests/wave29a_boards.py: both players' whole rules view on 15 tables built from real Oracle text (permissions from every zone, cost
  changers, alternative and optional costs, free casts, casting restrictions, layers, copies, mayhem, spell grants, hidden cards, the other
  player's turn, 3 spells on the stack) and 30 views along a turn and a half of play. The pass must give the same bytes.
  (Wave 30Q: Muldrotha's and Lurrus's lines are read now, so the ``permissions`` board and the ``play_through`` sequence list the land and the
  Mind Stone they allow from the graveyard; nothing else in the golden moved.)
  (Wave 43B: Bolas's Citadel is read, so the ``permissions`` board lists the Eternal Witness on top of the library as a free cast for p1, paying
  life; nothing else in the golden moved.)
* the same boards with the pass switched off (the old code path, still there for every engine action) must give the same views;
* a pass is read-only by construction: the table is the same at the end, and no value is stored in it while the table differs from its start;
* it ends with the call (nothing survives to the next action), belongs to one thread, one table object and one card info, and a probe's copy of
  a card is never answered from it;
* hints still only describe what their viewer may see (400.2), and replaying the game reproduces the table whatever was viewed on the way."""

from __future__ import annotations

import json
import threading
import time
from contextlib import nullcontext
from pathlib import Path

import pytest

from app.game.session import GameSession
from app.game.visibility import can_see
from app.rules import characteristics as chars
from app.rules import layers, read_pass
from app.rules.view import hints, rules_view
from tests.test_rules_effects import replay_matches
from tests.wave29a_boards import BOARDS, SEQUENCES
from tests.wave29a_kit import all_cards, snapshot, token

GOLDEN = json.loads((Path(__file__).parent / "fixtures" / "wave29a_hints_golden.json").read_text("utf-8"))
HINT_KEYS = ("playable_lands", "activatable", "castable", "x_cast", "free_castable", "alt_castable", "optional_costs")


@pytest.fixture()
def card_db(settings):
    from app.cards.importer import build_database

    settings.ensure_dirs()
    build_database(all_cards(), settings.cards_db_path, meta={"bulk_type": "test"})
    return settings.cards_db_path


# -- the same answers as before the pass existed ------------------------------------------------------------------
@pytest.mark.parametrize("name", sorted(BOARDS))
def test_hints_and_stats_equal_the_views_the_old_code_computed(cards, name):
    assert snapshot(BOARDS[name](cards)) == GOLDEN[name]


@pytest.mark.parametrize("name", sorted(SEQUENCES))
def test_every_view_along_a_turn_equals_the_old_ones(cards, name):
    got = SEQUENCES[name](cards)
    assert len(got) == len(GOLDEN[name]) >= 20
    for i, (now, before) in enumerate(zip(got, GOLDEN[name], strict=True)):
        assert now == before, f"step {i}"


def test_the_snapshots_exercise_every_kind_of_hint():
    """A golden that never lists anything would prove nothing: each hint is non-empty on some table, for both players, and the tables hold
    restricted, free, alternative and optional casts."""
    seen: dict[str, set[str]] = {}
    for name, case in GOLDEN.items():
        for snap in case if isinstance(case, list) else [case]:
            for pid, view in snap.items():
                for key in HINT_KEYS:
                    if view["hints"].get(key):
                        seen.setdefault(key, set()).add(f"{name}/{pid}")
    assert set(seen) == set(HINT_KEYS), set(HINT_KEYS) - set(seen)
    assert any(w.endswith("/p2") for w in seen["castable"])  # Bob's hints too
    assert len(seen["castable"]) >= 12 and len(seen["alt_castable"]) >= 5


@pytest.mark.parametrize("name", ["top_of_library", "restrictions_after_a_spell", "layers_and_copies", "second_player", "hidden_information", "free_casts"])  # (the old path is the slow one: the golden covers all the boards)
def test_the_uncached_path_gives_the_same_views(cards, monkeypatch, name):
    s = BOARDS[name](cards)
    cached = snapshot(s)
    monkeypatch.setattr(read_pass, "scope", lambda state, info: nullcontext())  # no pass: every question asked afresh, as every engine action does
    assert snapshot(s) == cached


# -- a pass only reads ----------------------------------------------------------------------------------------------
@pytest.mark.parametrize("name", ["stack_and_anthems", "permissions", "cost_changers", "layers_and_copies", "restrictions_after_a_spell",
                                  "alternative_costs", "hidden_information"])
def test_viewing_changes_nothing_and_stores_nothing_while_the_table_differs(cards, monkeypatch, name):
    s = BOARDS[name](cards)
    before = s.state.model_dump_json()
    stores = []

    class Guarded(dict):
        """A store that refuses to take a value while the table differs from the table the pass was opened on."""

        def __init__(self, state, start):
            super().__init__()
            self.state, self.start = state, start

        def __setitem__(self, key, value):
            stores.append(key)
            assert self.state.model_dump_json() == self.start, "the table changed while a read-only pass was open"
            super().__setitem__(key, value)

    real_init = read_pass.ReadPass.__init__

    def guarded_init(self, state, info):
        real_init(self, state, info)
        start = state.model_dump_json()
        self.derived, self.printed, self.once = (Guarded(state, start) for _ in range(3))

    monkeypatch.setattr(read_pass.ReadPass, "__init__", guarded_init)
    snapshot(s)
    assert len(stores) > 20  # (the guard really ran: derived values, printed values and table scans were stored)
    assert s.state.model_dump_json() == before


# -- the pass ends with the call, belongs to one table, one thread -------------------------------------------------------
def test_nothing_survives_the_call_and_a_later_action_is_seen(cards):
    s = BOARDS["stack_and_anthems"](cards)
    first = snapshot(s)
    assert read_pass.for_info(cards) is None  # (closed)
    bear = token(s, "p1", "Bear", "2/2")
    here = s.state.cards[bear.id]
    assert layers.derive(s.state, here, chars.of(here, cards), cards).pt == (2, 3)  # Banner +1/+1, Cumber -1/-0: the table changed, and derive reads it
    second = snapshot(s)
    assert second["p1"]["stats"] != first["p1"]["stats"]  # (the new creature, with the anthem, is in the second view and not in the first)


def test_a_pass_closes_when_the_block_raises(cards):
    s = BOARDS["top_of_library"](cards)
    with pytest.raises(RuntimeError), read_pass.scope(s.state, cards):
        assert read_pass.current(s.state, cards) is not None
        raise RuntimeError("boom")
    assert read_pass.current(s.state, cards) is None and read_pass.for_info(cards) is None


def test_a_pass_serves_only_the_table_object_it_was_opened_on(cards):
    s = BOARDS["stack_and_anthems"](cards)
    state = s.state
    banner = next(c for c in state.cards.values() if c.name == "A0" and c.owner == "p1")
    with read_pass.scope(state, cards) as sc:
        base = layers.derive(state, banner, chars.of(banner, cards), cards)
        assert sc.derived  # (kept)
        # a scratch copy of the table with the creature changed is a different table: nothing is answered from the pass
        scratch = state.model_copy(deep=True)
        mine = scratch.cards[banner.id]
        mine.counters["+1/+1"] = 2
        assert read_pass.current(scratch, cards) is None
        assert layers.derive(scratch, mine, chars.of(mine, cards), cards).pt == (base.pt[0] + 2, base.pt[1] + 2)
        assert layers.derive(state, banner, chars.of(banner, cards), cards) is base  # the real card is answered from the pass
        # a probe's copy of the real card (the same id, another zone) is not the card in the table: derived afresh
        probe = banner.model_copy(update={"zone": "p1:graveyard"})
        assert layers.derive(state, probe, chars.of(probe, cards), cards).pt == (2, 2) != base.pt  # (no anthem off the battlefield)
        # another card info is another pass
        assert read_pass.current(state, object()) is None
    assert layers.derive(state, banner, chars.of(banner, cards), cards) == base  # (outside the pass: the same value, computed again)


@pytest.mark.parametrize(("name", "part_way"), [("memo", [None, None, None]), ("depth", 1), ("solving", [[]]),
                                                 ("l4", {"x"}), ("cda", {"x"})])  # (review 29A: this thread's derivation, layers._T)
def test_nothing_is_kept_or_served_while_a_derivation_is_part_way(cards, monkeypatch, name, part_way):
    """A derivation that is running (or the group layers being solved) reads a half-finished table: what a question has then is not what it has
    when nothing is part-way, so the pass neither stores it nor answers from what it stored."""
    s = BOARDS["top_of_library"](cards)
    with read_pass.scope(s.state, cards) as sc:
        assert read_pass.once(s.state, cards, "k", lambda: 1) == 1
        assert read_pass.once(s.state, cards, "k", lambda: 2) == 1  # (settled: answered from the pass)
        monkeypatch.setattr(layers._T, name, part_way)
        assert not layers.settled()
        assert read_pass.once(s.state, cards, "k", lambda: 3) == 3  # part-way: asked afresh
        assert read_pass.once(s.state, cards, "j", lambda: 4) == 4 and "j" not in sc.once  # and not kept
        monkeypatch.undo()
        assert layers.settled() and read_pass.once(s.state, cards, "k", lambda: 5) == 1


def test_a_pass_belongs_to_the_thread_that_opened_it(cards):
    s = BOARDS["top_of_library"](cards)
    seen = []
    with read_pass.scope(s.state, cards):
        t = threading.Thread(target=lambda: seen.append((read_pass.current(s.state, cards), read_pass.for_info(cards))))
        t.start()
        t.join()
        assert read_pass.current(s.state, cards) is not None
    assert seen == [(None, None)]


def test_nested_views_share_the_open_pass(cards):
    s = BOARDS["top_of_library"](cards)
    with read_pass.scope(s.state, cards) as outer, read_pass.scope(s.state, cards) as inner:
        assert inner is outer
    assert read_pass.current(s.state, cards) is None


# -- fast ------------------------------------------------------------------------------------------------------------
def test_a_view_derives_each_permanent_a_handful_of_times_not_once_per_card_and_ability(cards, monkeypatch):
    """Counted, not timed: before the pass, hints derived every permanent once for every (card in hand × static kind) question — ~4,900
    derivations on this table. Now each permanent is derived once for the view and the few cards asked about add their own."""
    s = BOARDS["stack_and_anthems"](cards)
    field = sum(1 for c in s.state.cards.values() if c.zone.endswith(":battlefield"))
    assert field >= 75 and len(s.state.zones["stack"]) == 3 and len(s.state.zones["p1:hand"]) == 7
    hints(s.state, "p1", cards)  # (warm: parsed card text, the statics cache)
    calls = []
    real = layers._derive
    monkeypatch.setattr(layers, "_derive", lambda *a, **k: (calls.append(a[1].id), real(*a, **k))[1])
    hints(s.state, "p1", cards)
    assert len(calls) <= 2 * field, f"{len(calls)} derivations for {field} permanents"  # (88; the old code: 5,767)
    assert max(calls.count(c) for c in set(calls)) <= 6  # (the commander: asked about as a card in the command zone and as the Krenko it is)


def test_hints_on_80_permanents_with_spells_on_the_stack_take_a_fraction_of_a_second(cards):
    s = BOARDS["stack_and_anthems"](cards)
    hints(s.state, "p1", cards)  # (warm: parsed card text)
    best = min(_timed(lambda: hints(s.state, "p1", cards)) for _ in range(5))
    assert best < 0.4, f"{best * 1000:.0f} ms for the hints (was ~1.2-2.5 s)"  # (≈25 ms; the old code took seconds)


def _timed(fn):
    t0 = time.perf_counter()
    fn()
    return time.perf_counter() - t0


# -- hidden information and replay -----------------------------------------------------------------------------------
@pytest.mark.parametrize("name", sorted(BOARDS))
def test_hints_only_name_cards_their_viewer_may_see(cards, name):
    s = BOARDS[name](cards)
    for pid in s.state.players:
        h = hints(s.state, pid, cards)
        if not h["has_priority"]:
            assert set(h) <= {"has_priority", "miracle"}, f"{pid}: {set(h)}"  # nothing about anyone's cards without priority
            continue
        offered = {*h["playable_lands"], *h["castable"], *h["free_castable"], *h.get("alt_castable", {}), *h.get("optional_costs", {}), *h.get("x_cast", [])}
        for cid in offered:
            card = s.state.cards[cid]
            assert card.owner == pid and can_see(s.state, card, pid), f"{pid} is offered {card.name} ({card.zone})"
        for entry in h["activatable"]:
            assert s.state.cards[entry["card_id"]].controller == pid


def test_a_face_down_exiled_card_nobody_looked_at_is_not_offered(cards):
    s = BOARDS["hidden_information"](cards)
    for pid in ("p1", "p2"):
        hidden = next(c for c in s.state.cards.values() if c.zone == f"{pid}:exile")
        assert hidden.face_down and hidden.unseen and not can_see(s.state, hidden, pid)  # (406.3: not even its owner has looked at it)
        assert hidden.id not in json.dumps(rules_view(s.state, pid, cards), default=str)  # not offered, not in the stats, nowhere in the view
    theirs = json.dumps(rules_view(s.state, "p2", cards), default=str)
    assert not any(c in theirs for c in [*s.state.zones["p1:hand"], *s.state.zones["p1:library"]])  # nothing of Alice's hand or library
    top = s.state.zones["p1:library"][0]
    assert top in hints(s.state, "p1", cards)["castable"]  # (Future Sight reveals the top card: it is offered)


def test_replay_reproduces_the_table_whatever_was_viewed_on_the_way(cards):
    s = BOARDS["stack_and_anthems"](cards)
    views = [snapshot(s)]
    session_view = s.view("p1")
    assert session_view["rules"]["hints"]["castable"]
    replay_matches(s)
    rebuilt = GameSession(s.history.rebuild(), cards=cards)
    assert snapshot(rebuilt) == views[0]  # (a table rebuilt from the recorded actions gives the very same views)
    assert rebuilt.view("p1")["rules"]["hints"] == session_view["rules"]["hints"]
